    // ============================================================
    // UNIVERSAL PARSERS & HELPERS (SHARED BY EXCEL IMPORT & PASTE)
    // ============================================================
    khmerToLatinDigits(str) {
      if (!str) return '';
      const kd = ['០','១','២','៣','៤','៥','៦','៧','៨','៩'];
      let res = String(str);
      kd.forEach((k, idx) => { res = res.replaceAll(k, String(idx)); });
      return res;
    },

    parseUniversalDate(val) {
      if (val === null || val === undefined) return '';
      let str = String(val).trim();
      if (!str) return '';

      str = str.replace(/[\u200B-\u200D\uFEFF]/g, '');
      str = this.khmerToLatinDigits(str);

      let m = str.match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})$/);
      if (m) {
        let d = m[1].padStart(2, '0');
        let mon = m[2].padStart(2, '0');
        let y = m[3];
        if (y.length === 2) {
          y = parseInt(y, 10) > 40 ? '19' + y : '20' + y;
        }
        return `${d}/${mon}/${y}`;
      }

      m = str.match(/^(\d{4})[\/\-\.](\d{1,2})[\/\-\.](\d{1,2})$/);
      if (m) {
        let y = m[1];
        let mon = m[2].padStart(2, '0');
        let d = m[3].padStart(2, '0');
        return `${d}/${mon}/${y}`;
      }

      const khmerMonths = {
        'មករា': '01', 'កុម្ភៈ': '02', 'កុម្ភះ': '02', 'មិនា': '03', 'មីនា': '03',
        'មេសា': '04', 'ឧសភា': '05', 'មិថុនា': '06', 'កក្កដា': '07', 'សីហា': '08',
        'កញ្ញា': '09', 'តុលា': '10', 'វិច្ឆិកា': '11', 'ធ្នូ': '12'
      };

      for (const [kMon, monNum] of Object.entries(khmerMonths)) {
        if (str.includes(kMon)) {
          const parts = str.replace(kMon, ` ${monNum} `).trim().split(/\s+/);
          if (parts.length >= 3) {
            let d = parts[0].replace(/[^\d]/g, '').padStart(2, '0');
            let mon = parts[1].padStart(2, '0');
            let y = parts[2].replace(/[^\d]/g, '');
            if (y.length === 2) y = parseInt(y, 10) > 40 ? '19' + y : '20' + y;
            if (d && mon && y) return `${d}/${mon}/${y}`;
          }
        }
      }

      const num = Number(str);
      if (!isNaN(num) && num > 10000 && num < 60000) {
        const date = new Date(Math.round((num - 25569) * 86400 * 1000));
        const d = String(date.getUTCDate()).padStart(2, '0');
        const mon = String(date.getUTCMonth() + 1).padStart(2, '0');
        const y = date.getUTCFullYear();
        return `${d}/${mon}/${y}`;
      }

      return str;
    },

    splitCambodianAddress(rawAddr) {
      if (!rawAddr) return { village: '', commune: '', district: '', province: '' };
      let str = String(rawAddr).trim();
      if (!str) return { village: '', commune: '', district: '', province: '' };

      let v = '', c = '', d = '', p = '';

      const vMatch = str.match(/ភូមិ\s*(.+?)(?=\s*(?:ឃុំ|សង្កាត់|ស្រុក|ខណ្ឌ|ក្រុង|ខេត្ត|រាជធានី|$))/);
      if (vMatch) v = vMatch[1].trim();

      const cMatch = str.match(/(?:ឃុំ|សង្កាត់)\s*(.+?)(?=\s*(?:ស្រុក|ខណ្ឌ|ក្រុង|ខេត្ត|រាជធានី|$))/);
      if (cMatch) c = cMatch[1].trim();

      const dMatch = str.match(/(?:ស្រុក|ខណ្ឌ|ក្រុង)\s*(.+?)(?=\s*(?:ខេត្ត|រាជធានី|$))/);
      if (dMatch) d = dMatch[1].trim();

      const pMatch = str.match(/(?:ខេត្ត|រាជធានី)\s*(.+?)$/);
      if (pMatch) p = pMatch[1].trim();

      return { village: v, commune: c, district: d, province: p };
    },

    formatPhone(val) {
      if (!val) return '';
      let str = String(val).trim().replace(/[^\d+]/g, '');
      if (/^[1-9]\d{7,8}$/.test(str)) {
        return '0' + str;
      }
      return str;
    },

    cleanVal(val) {
      if (val === null || val === undefined) return '';
      let str = String(val).trim();
      if (str.startsWith('$') && /^(\$|\s)*\d+/.test(str)) {
        str = str.replace(/^\$/, '').trim();
      }
      return str;
    },

    normalizeGender(val) {
      if (!val) return 'ប';
      let str = String(val).trim().toLowerCase();
      if (str === 'ស' || str === 'ស្រី' || str === 'f' || str === 'female' || str === 'g' || str === 'girl' || str.includes('ស្រី')) {
        return 'ស';
      }
      if (str === 'ប' || str === 'ប្រុស' || str === 'm' || str === 'male' || str === 'b' || str === 'boy' || str.includes('ប្រុស')) {
        return 'ប';
      }
      return 'ប';
    },

